"""
Point coding agents (Claude Code, Codex) at the qBraid AI proxy, reversibly.

Each agent is configured through its own on-disk config, and every value we
overwrite is recorded first so ``disconnect_agent`` can put the user's setup
back exactly as it was — including the difference between "the key held some
other value" and "the key wasn't there at all".

Neither agent is given the API key directly. Both support running a command
that prints a token to stdout (Claude Code's ``apiKeyHelper``, Codex's
``[model_providers.<id>.auth]``), so the key stays in qbraidrc and never lands
in a file the user is likely to share or commit.
"""

import json
import logging
import os
import re
import shutil
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Optional

from .exceptions import AiGatewayError

logger = logging.getLogger(__name__)

SUPPORTED_AGENTS = ("claude", "codex")

# Path segment appended to the configured qBraid API base to reach the proxy.
_AI_PATH = "ai"

# Command the agents run to obtain a token. Kept as argv rather than a shell
# string so neither agent has to word-split it.
#
# Running a command rather than writing the credential is what makes expiry
# survivable: each agent re-invokes this on an interval, and the command
# re-reads the environment and qbraidrc every time. When a Lab pod rotates
# QBRAID_ACCESS_TOKEN, the next refresh picks up the new one with no user
# action and no reconnect.
#
# Points at the dedicated `qbraid-ai-token` script rather than `qbraid ai
# token`: the full CLI imports every command group (~0.9s) to print one string,
# where the standalone entry point costs ~0.2s and stays flat as the CLI grows.
# `qbraid ai token` still exists for humans debugging this.
_TOKEN_ARGV = ("qbraid-ai-token",)

# How often each agent re-runs the token command. Five minutes matches Codex's
# own default and bounds how long a rotated credential can go unnoticed.
_TOKEN_REFRESH_MS = 300_000

# The proxy resolves a model by exact alias lookup — no prefix match and no
# date-suffix stripping. Claude Code's own defaults are dated
# ("claude-sonnet-4-5-20250929") and newer ones aren't in the registry at all,
# so leaving `model` unset means the first request fails on an unknown model.
# Pin a known-good id on connect; `qbraid ai models` lists the alternatives.
_DEFAULT_CLAUDE_MODEL = "claude-sonnet-4-6"
# Codex needs one for the same reason: with `model` unset it sends its own
# default, which the proxy's exact-match lookup rejects. Codex speaks the
# Responses API, so the GPT family is the sane default there.
_DEFAULT_CODEX_MODEL = "gpt-5.4"

# Codex reserves "openai", "ollama" and "lmstudio", so the provider needs its
# own id. Also doubles as the marker for the block we manage.
_CODEX_PROVIDER_ID = "qbraid"
_CODEX_BEGIN = "# >>> qbraid ai gateway >>>"
_CODEX_END = "# <<< qbraid ai gateway <<<"
# Prefix used to park a pre-existing top-level model_provider line so TOML
# doesn't see a duplicate key. Removing the prefix restores it verbatim.
_CODEX_PARKED = "# qbraid-ai-gateway parked: "
# Inline tag on the top-level keys we write. They can't live inside the
# BEGIN/END block (TOML wants bare keys before the first table, and the block
# is a table), so they need their own way to be recognised and removed.
_CODEX_TAG = "  # qbraid-ai-gateway"

_CLAUDE_SETTINGS = Path.home() / ".claude" / "settings.json"
_CODEX_CONFIG = Path.home() / ".codex" / "config.toml"

# Keys we take over in Claude Code's settings.json. ANTHROPIC_API_KEY is in the
# list because a stale one left in the env block would take precedence over the
# helper — we clear it on connect and restore it on disconnect.
_CLAUDE_ENV_KEYS = (
    "ANTHROPIC_BASE_URL",
    "ANTHROPIC_API_KEY",
    "ANTHROPIC_AUTH_TOKEN",
    "CLAUDE_CODE_API_KEY_HELPER_TTL_MS",
)


def _state_path() -> Path:
    """Location of the sidecar recording what we overwrote."""
    config_file = os.getenv("QBRAID_CONFIG_FILE")
    base = Path(config_file).parent if config_file else Path.home() / ".qbraid"
    return base / "ai_gateway.json"


def _read_state() -> tuple[dict, bool]:
    """Return ``(state, readable)``.

    ``readable`` distinguishes "no sidecar yet" (a genuine first connect) from
    "the sidecar exists but we couldn't parse it". Collapsing those is how a
    transient read error turns into data loss: connect would treat its own
    already-applied settings as the user's originals, and disconnect would
    then faithfully "restore" the gateway.
    """
    path = _state_path()
    if not path.exists():
        return {}, True
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as err:
        logger.warning("Could not read AI gateway state at %s: %s", path, err)
        return {}, False

    if not isinstance(data, dict):
        logger.warning("AI gateway state at %s is not an object; ignoring.", path)
        return {}, False
    return data, True


def _entry(state: dict, agent: str) -> dict:
    """Return ``state[agent]`` when it's a usable record, else ``{}``.

    Hand-edited or half-written sidecars shouldn't surface as an
    ``AttributeError`` from somewhere deep in a restore.
    """
    entry = state.get(agent)
    return entry if isinstance(entry, dict) else {}


def _previous(entry: dict) -> dict:
    """Return the recorded pre-connect values, tolerating a damaged record."""
    previous = entry.get("previous")
    return previous if isinstance(previous, dict) else {}


def _atomic_write(path: Path, text: str, mode: int = 0o644) -> None:
    """Write ``text`` to ``path`` atomically, at ``mode``.

    ``settings.json`` is hot-reloaded by Claude Code and read by every agent on
    the machine, so a truncate-then-write leaves a window where readers see an
    empty or half-written file. Writing a sibling temp file and renaming makes
    the swap atomic; creating it with the final mode avoids briefly exposing a
    credential-bearing file at the default umask.
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.qbraid-tmp")
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, mode)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(text)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        tmp.unlink(missing_ok=True)
        raise


def _write_state(state: dict) -> None:
    # 0600: this records the user's prior ANTHROPIC_API_KEY when they had one.
    _atomic_write(_state_path(), json.dumps(state, indent=2) + "\n", mode=0o600)


def resolve_gateway_url(api_url: Optional[str] = None) -> str:
    """Return the AI proxy base URL for the user's configured API endpoint.

    Args:
        api_url: Override for the qBraid API base. Defaults to the configured
            endpoint, so a user pointed at staging gets the staging proxy.

    Returns:
        str: e.g. ``https://api-v2.qbraid.com/api/v1/ai``
    """
    if api_url is None:
        # Imported lazily: sessions pulls in requests, and callers that only
        # want to read status shouldn't pay for it.
        from qbraid_core.sessions import QbraidSession  # pylint: disable=import-outside-toplevel

        api_url = QbraidSession().base_url

    if not api_url:
        raise AiGatewayError("No qBraid API URL configured. Run `qbraid configure` and try again.")

    return f"{str(api_url).rstrip('/')}/{_AI_PATH}"


def resolve_credential() -> tuple[str, str]:
    """Return the credential the agents should present, and which kind it is.

    Mirrors :class:`~qbraid_core.sessions.QbraidSession`'s own precedence:
    an access token wins over an API key. That ordering matters in Lab user
    pods, which are provisioned with an access token and typically no API key.

    Returns:
        tuple[str, str]: ``(credential, kind)`` where kind is ``"access_token"``
        or ``"api_key"``.

    Raises:
        AiGatewayError: If neither credential is configured.
    """
    from qbraid_core.sessions import QbraidSession  # pylint: disable=import-outside-toplevel

    session = QbraidSession()
    if session.access_token:
        return session.access_token, "access_token"
    if session.api_key:
        return session.api_key, "api_key"

    raise AiGatewayError(
        "No qBraid credential found. Run `qbraid configure`, or set "
        "QBRAID_API_KEY / QBRAID_ACCESS_TOKEN."
    )


def credential_expired_hint(kind: str) -> str:
    """Guidance to show when the proxy rejects the current credential.

    The two credential types fail differently and want different advice: an
    access token is issued by the platform and rotates on its own, whereas an
    API key is user-managed and has to be replaced by hand.

    Args:
        kind: ``"access_token"`` or ``"api_key"``.

    Returns:
        str: A one-or-two line message for the user.
    """
    if kind == "access_token":
        return (
            "Your qBraid access token was rejected. Tokens rotate periodically; "
            f"the agent re-reads it every {_TOKEN_REFRESH_MS // 60000} minutes, so a "
            "freshly issued one is picked up automatically. If it keeps failing, "
            "restart the session so QBRAID_ACCESS_TOKEN is re-read from the "
            "environment."
        )
    return (
        "Your qBraid API key was rejected. Generate a new one at "
        "https://account.qbraid.com and save it with `qbraid configure`. "
        "No need to reconnect — the agent picks up the new key on its next refresh."
    )


def token_command() -> tuple[str, ...]:
    """The argv the agents run to obtain a credential.

    Exposed so callers can check the executable actually resolves — the agents
    invoke it by bare name, and a PATH that doesn't include it fails silently
    as a 401 rather than as a missing command.
    """
    return _TOKEN_ARGV


def _token_command_display() -> str:
    """The token command as a shell string, for config formats that want one."""
    return " ".join(_TOKEN_ARGV)


def list_models() -> list[dict]:
    """List the models the proxy will serve for this account.

    Returns:
        list[dict]: Model records as returned by ``GET {gateway}/models``.
    """
    from qbraid_core.sessions import QbraidSession  # pylint: disable=import-outside-toplevel

    session = QbraidSession()
    payload = session.get(f"{_AI_PATH}/models").json()
    data = payload.get("data", payload)
    return data if isinstance(data, list) else data.get("models", [])


def get_quota() -> dict:
    """Return the account's remaining AI quota.

    Returns:
        dict: Quota record as returned by ``GET {gateway}/quota``.
    """
    from qbraid_core.sessions import QbraidSession  # pylint: disable=import-outside-toplevel

    session = QbraidSession()
    payload = session.get(f"{_AI_PATH}/quota").json()
    data = payload.get("data", payload)
    return data if isinstance(data, dict) else {}


# --------------------------------------------------------------------------- #
# Claude Code
# --------------------------------------------------------------------------- #
def _load_claude_settings() -> dict:
    if not _CLAUDE_SETTINGS.exists():
        return {}
    try:
        with open(_CLAUDE_SETTINGS, "r", encoding="utf-8") as f:
            settings = json.load(f)
        return settings if isinstance(settings, dict) else {}
    except (json.JSONDecodeError, OSError) as err:
        # Overwriting a settings file we failed to parse would destroy the
        # user's whole Claude Code configuration, so refuse instead.
        raise AiGatewayError(
            f"Could not parse {_CLAUDE_SETTINGS}: {err}. " "Fix or move the file, then retry."
        ) from err


def _backup_once(path: Path) -> None:
    """Snapshot ``path`` the first time we touch it, and never again.

    Re-copying on every write destroys the thing a backup is for: the second
    operation would overwrite the pristine original with our own output.
    """
    backup = path.with_name(path.name + ".qbraid-bak")
    if path.exists() and not backup.exists():
        shutil.copy2(path, backup)
        try:
            # May contain a credential if the user had one inline; don't leave
            # it more readable than the file it came from.
            backup.chmod(0o600)
        except OSError:  # pragma: no cover - non-POSIX
            pass


def _save_claude_settings(settings: dict) -> None:
    _backup_once(_CLAUDE_SETTINGS)
    _atomic_write(_CLAUDE_SETTINGS, json.dumps(settings, indent=2) + "\n")


def _connect_claude(
    gateway_url: str,
    api_key: Optional[str],
    model: Optional[str] = None,
    refresh_ms: int = _TOKEN_REFRESH_MS,
) -> dict:
    """Route Claude Code at the proxy via ``env`` + ``apiKeyHelper``."""
    settings = _load_claude_settings()
    env = settings.get("env")
    if not isinstance(env, dict):
        env = {}

    state, readable = _read_state()
    if not readable:
        # Re-snapshotting here would record our own already-applied settings as
        # the user's originals, and disconnect would then restore the gateway
        # instead of removing it. Refuse rather than silently lose their config.
        raise AiGatewayError(
            f"Could not read {_state_path()}, so the settings recorded before "
            "connecting can't be trusted. Fix or remove that file and retry — "
            "removing it means disconnect can no longer restore your previous "
            f"configuration, which is backed up at {_CLAUDE_SETTINGS}.qbraid-bak."
        )

    # Only capture the pre-existing values on a first connect. Re-connecting
    # must not overwrite the snapshot with our own settings, or disconnect
    # would "restore" the gateway it was meant to remove.
    if "claude" not in state:
        previous: dict[str, Any] = {f"env.{k}": env.get(k) for k in _CLAUDE_ENV_KEYS}
        previous["apiKeyHelper"] = settings.get("apiKeyHelper")
        previous["model"] = settings.get("model")
    else:
        previous = _previous(_entry(state, "claude"))

    env["ANTHROPIC_BASE_URL"] = gateway_url

    if api_key:
        # Explicit opt-in to a literal key (e.g. a machine with no qbraid CLI
        # on PATH for the helper to invoke).
        env["ANTHROPIC_API_KEY"] = api_key
        settings.pop("apiKeyHelper", None)
        auth_mode = "api_key"
    else:
        settings["apiKeyHelper"] = _token_command_display()
        # Written explicitly rather than left to the default so --refresh-interval
        # actually takes effect; the value happens to match Claude Code's own
        # default when the flag isn't used.
        env["CLAUDE_CODE_API_KEY_HELPER_TTL_MS"] = str(refresh_ms)
        # A leftover key would win over the helper; drop it (restorable).
        env.pop("ANTHROPIC_API_KEY", None)
        env.pop("ANTHROPIC_AUTH_TOKEN", None)
        auth_mode = "api_key_helper"

    # The proxy matches model ids exactly, so an unpinned Claude Code would
    # send its own (dated) default and get an unknown-model error on the very
    # first request. Pin one the proxy knows.
    selected_model = model or _DEFAULT_CLAUDE_MODEL
    settings["model"] = selected_model

    settings["env"] = env
    _save_claude_settings(settings)

    state["claude"] = {
        "connected_at": datetime.now(timezone.utc).isoformat(),
        "gateway_url": gateway_url,
        "auth_mode": auth_mode,
        "model": selected_model,
        "previous": previous,
        # What we actually wrote. Disconnect removes a key only when it still
        # holds our value — otherwise a missing snapshot, or a value the user
        # set afterwards, would be deleted as though it were ours.
        "written": {
            **{f"env.{k}": env.get(k) for k in _CLAUDE_ENV_KEYS if k in env},
            "apiKeyHelper": settings.get("apiKeyHelper"),
            "model": selected_model,
        },
    }
    _write_state(state)

    return {
        "agent": "claude",
        "status": "connected",
        "path": str(_CLAUDE_SETTINGS),
        "gateway_url": gateway_url,
        "auth_mode": auth_mode,
        "model": selected_model,
    }


def _restore_key(container: dict, key: str, prior: Any, ours: Any) -> None:
    """Put ``key`` back the way it was, without deleting anything of the user's.

    Removal happens only when the key still holds the value *we* wrote. That
    covers both a missing snapshot (we then know nothing was ours) and a value
    the user set after connecting (theirs to keep).
    """
    if prior is not None:
        container[key] = prior
    elif ours is not None and container.get(key) == ours:
        container.pop(key, None)


def _recognisable_ours(settings: dict, env: dict) -> dict:
    """Values identifiable as ours from their content alone.

    Used when the sidecar is gone: without it we can't know what the user had,
    but we can still recognise what *we* write, which is what lets disconnect
    un-stick someone whose state file was deleted. Anything not recognised is
    left untouched on the assumption it's theirs.
    """
    ours: dict[str, Any] = {}

    helper = _token_command_display()
    if settings.get("apiKeyHelper") == helper:
        ours["apiKeyHelper"] = helper
        # Only meaningful alongside our helper; on its own it could be theirs.
        ttl = env.get("CLAUDE_CODE_API_KEY_HELPER_TTL_MS")
        if ttl is not None:
            ours["env.CLAUDE_CODE_API_KEY_HELPER_TTL_MS"] = ttl

    base = env.get("ANTHROPIC_BASE_URL")
    if isinstance(base, str) and base.rstrip("/").endswith(f"/{_AI_PATH}"):
        try:
            if base == resolve_gateway_url():
                ours["env.ANTHROPIC_BASE_URL"] = base
        except AiGatewayError:  # pragma: no cover - unconfigured install
            pass

    return ours


def _disconnect_claude() -> dict:
    """Restore Claude Code's previous settings."""
    state, _ = _read_state()
    entry = _entry(state, "claude")

    if not _CLAUDE_SETTINGS.exists():
        state.pop("claude", None)
        _write_state(state)
        return {"agent": "claude", "status": "not_configured"}

    settings = _load_claude_settings()
    env = settings.get("env")
    if not isinstance(env, dict):
        env = {}

    previous = _previous(entry)
    written = entry.get("written")
    written = written if isinstance(written, dict) else {}
    if not written:
        # No record — fall back to what we can identify by value, so a deleted
        # sidecar doesn't leave the user permanently routed at the gateway.
        written = _recognisable_ours(settings, env)

    for key in _CLAUDE_ENV_KEYS:
        _restore_key(env, key, previous.get(f"env.{key}"), written.get(f"env.{key}"))

    _restore_key(
        settings,
        "apiKeyHelper",
        previous.get("apiKeyHelper"),
        written.get("apiKeyHelper", _token_command_display()),
    )
    _restore_key(
        settings,
        "model",
        previous.get("model"),
        written.get("model", entry.get("model")),
    )

    if env:
        settings["env"] = env
    else:
        settings.pop("env", None)

    _save_claude_settings(settings)

    state.pop("claude", None)
    _write_state(state)

    return {
        "agent": "claude",
        "status": "disconnected" if entry else "cleared",
        "path": str(_CLAUDE_SETTINGS),
        "restored": bool(entry),
    }


def _status_claude() -> dict:
    settings: dict = {}
    if _CLAUDE_SETTINGS.exists():
        try:
            settings = _load_claude_settings()
        except AiGatewayError:
            return {"agent": "claude", "connected": False, "error": "unparseable settings.json"}

    raw_env = settings.get("env")
    env: dict = raw_env if isinstance(raw_env, dict) else {}
    base_url = env.get("ANTHROPIC_BASE_URL")
    entry = _entry(_read_state()[0], "claude")

    return {
        "agent": "claude",
        "installed": _CLAUDE_SETTINGS.exists(),
        "connected": bool(base_url) and base_url == entry.get("gateway_url"),
        "base_url": base_url,
        # Read from settings.json rather than the sidecar so a model the user
        # switched to after connecting is reported accurately.
        "model": settings.get("model") or entry.get("model"),
        "auth_mode": entry.get("auth_mode"),
        "connected_at": entry.get("connected_at"),
        "path": str(_CLAUDE_SETTINGS),
    }


# --------------------------------------------------------------------------- #
# Codex
# --------------------------------------------------------------------------- #
def _codex_block(
    gateway_url: str,
    model: Optional[str],
    api_key_env: Optional[str],
    refresh_ms: int = _TOKEN_REFRESH_MS,
) -> str:
    """Render the managed ``[model_providers.qbraid]`` block.

    ``wire_api`` is omitted: ``responses`` is the only supported value and the
    default, and the proxy exposes ``/responses`` under the same base.
    """
    lines = [
        _CODEX_BEGIN,
        f"# Managed by `qbraid ai connect codex` — edits here are overwritten.{_CODEX_TAG}",
        f"# Remove with `qbraid ai disconnect codex`.{_CODEX_TAG}",
        f"[model_providers.{_CODEX_PROVIDER_ID}]",
        'name = "qBraid"',
        f'base_url = "{gateway_url}"',
    ]
    if api_key_env:
        lines.append(f'env_key = "{api_key_env}"')
    else:
        lines += [
            "",
            f"[model_providers.{_CODEX_PROVIDER_ID}.auth]",
            f'command = "{_TOKEN_ARGV[0]}"',
        ]
        if len(_TOKEN_ARGV) > 1:
            rendered = ", ".join(f'"{arg}"' for arg in _TOKEN_ARGV[1:])
            lines.append(f"args = [{rendered}]")
        lines += [
            # Re-run on an interval so a rotated access token is picked up
            # without reconnecting.
            f"refresh_interval_ms = {refresh_ms}",
        ]
    lines.append(_CODEX_END)
    return "\n".join(lines)


# Banner comments we emit above the managed table. Matched by text as well as
# by tag so a config written by an earlier build — whose banners predate the
# tag — is still cleaned up rather than leaving orphan comments behind.
_CODEX_BANNERS = (
    "# Managed by `qbraid ai connect codex`",
    "# Remove with `qbraid ai disconnect codex`",
)


def _is_managed_line(line: str) -> bool:
    """Whether ``line`` is something we wrote (and may remove)."""
    stripped = line.strip()
    return line.rstrip().endswith(_CODEX_TAG) or stripped.startswith(_CODEX_BANNERS)


def _strip_codex_managed(text: str) -> list[str]:
    """Drop everything we previously wrote, returning the user's own lines.

    Removal is content-based, never positional. Codex rewrites config.toml at
    runtime — it appends its own ``[projects]``, ``[hooks.state]`` and
    ``[tui.*]`` tables, and those can land *between* our begin/end markers.
    Deleting "everything between the markers" would then take the user's own
    state with it, so we instead remove exactly three things:

      * our marker comments,
      * top-level keys carrying our inline tag,
      * the ``[model_providers.<id>]`` table and its subtables.

    A table is removed from its header up to the next header, so anything
    Codex interleaved survives untouched.
    """
    kept: list[str] = []
    in_our_table = False

    for line in text.splitlines():
        stripped = line.strip()

        if stripped in (_CODEX_BEGIN, _CODEX_END):
            continue

        if stripped.startswith("["):
            # A new table starts: it's ours only if it's the provider we manage.
            in_our_table = stripped.startswith(
                f"[model_providers.{_CODEX_PROVIDER_ID}]"
            ) or stripped.startswith(f"[model_providers.{_CODEX_PROVIDER_ID}.")
            if in_our_table:
                continue

        if in_our_table:
            # Body of our table — including the comments we wrote above it.
            continue

        if _is_managed_line(line):
            continue

        kept.append(line)

    return kept


def _split_top_level(lines: list[str]) -> tuple[list[str], list[str]]:
    """Split into (lines before the first table header, the rest).

    TOML requires bare top-level keys to appear before any ``[table]``, so our
    ``model_provider`` / ``model`` have to be inserted into the first half.
    """
    for idx, line in enumerate(lines):
        if line.lstrip().startswith("["):
            return lines[:idx], lines[idx:]
    return lines, []


def _park_conflicting(head: list[str], keys: tuple[str, ...]) -> list[str]:
    """Comment out live top-level ``keys`` so ours aren't duplicates.

    TOML rejects a duplicate key outright, so a user's own ``model_provider``
    has to be moved aside rather than left in place. The prefix is removed
    verbatim on disconnect.
    """
    parked = []
    for line in head:
        bare = line.lstrip()
        is_live = not bare.startswith("#")
        if is_live and any(re.match(rf"\s*{k}\s*=", line) for k in keys):
            parked.append(f"{_CODEX_PARKED}{line}")
        else:
            parked.append(line)
    return parked


def _connect_codex(
    gateway_url: str,
    model: Optional[str],
    api_key_env: Optional[str],
    refresh_ms: int = _TOKEN_REFRESH_MS,
) -> dict:
    """Route Codex at the proxy via a managed provider block in config.toml."""
    _CODEX_CONFIG.parent.mkdir(parents=True, exist_ok=True)
    original = ""
    existed = _CODEX_CONFIG.exists()
    if existed:
        try:
            original = _CODEX_CONFIG.read_text(encoding="utf-8")
        except OSError as err:
            raise AiGatewayError(f"Could not read {_CODEX_CONFIG}: {err}") from err
        _backup_once(_CODEX_CONFIG)

    state, readable = _read_state()
    if not readable:
        raise AiGatewayError(
            f"Could not read {_state_path()}, so the settings recorded before "
            "connecting can't be trusted. Fix or remove that file and retry — "
            f"your original config is backed up at {_CODEX_CONFIG}.qbraid-bak."
        )

    first_connect = "codex" not in state
    previous = {"config_existed": existed} if first_connect else _previous(_entry(state, "codex"))

    # Drop anything we wrote before, so a reconnect replaces rather than stacks.
    head, tail = _split_top_level(_strip_codex_managed(original))

    # `model` is only parked when we're about to set one — otherwise the user's
    # own choice should stay live.
    model = model or _DEFAULT_CODEX_MODEL
    conflicts = ("model_provider", "model")
    head = _park_conflicting(head, conflicts)

    new_head = [f'model_provider = "{_CODEX_PROVIDER_ID}"{_CODEX_TAG}']
    if model:
        new_head.append(f'model = "{model}"{_CODEX_TAG}')
    new_head.extend(head)

    body = "\n".join(new_head + tail).rstrip("\n")
    block = _codex_block(gateway_url, model, api_key_env, refresh_ms)
    _atomic_write(_CODEX_CONFIG, f"{body}\n\n{block}\n" if body else f"{block}\n")

    state["codex"] = {
        "connected_at": datetime.now(timezone.utc).isoformat(),
        "gateway_url": gateway_url,
        "auth_mode": "env_key" if api_key_env else "auth_command",
        "model": model,
        "previous": previous,
    }
    _write_state(state)

    return {
        "agent": "codex",
        "status": "connected",
        "path": str(_CODEX_CONFIG),
        "gateway_url": gateway_url,
        "auth_mode": "env_key" if api_key_env else "auth_command",
        "provider_id": _CODEX_PROVIDER_ID,
    }


def _disconnect_codex() -> dict:
    """Remove everything we wrote and un-park the user's own keys."""
    state, _ = _read_state()
    entry = _entry(state, "codex")

    if not _CODEX_CONFIG.exists():
        state.pop("codex", None)
        _write_state(state)
        return {"agent": "codex", "status": "not_configured"}

    try:
        text = _CODEX_CONFIG.read_text(encoding="utf-8")
    except OSError as err:
        raise AiGatewayError(f"Could not read {_CODEX_CONFIG}: {err}") from err

    # Removes both the provider block and our tagged top-level keys, so no
    # dangling `model_provider = "qbraid"` is left pointing at a block that
    # no longer exists.
    restored_lines = [
        line[len(_CODEX_PARKED) :] if line.startswith(_CODEX_PARKED) else line
        for line in _strip_codex_managed(text)
    ]

    body = "\n".join(restored_lines).strip("\n")
    if body:
        _atomic_write(_CODEX_CONFIG, body + "\n")
    elif not _previous(entry).get("config_existed", True):
        # We created the file; leaving an empty one behind is litter.
        _CODEX_CONFIG.unlink()
    else:
        _atomic_write(_CODEX_CONFIG, "")

    state.pop("codex", None)
    _write_state(state)

    return {
        "agent": "codex",
        "status": "disconnected" if entry else "cleared",
        "path": str(_CODEX_CONFIG),
        "restored": bool(entry),
    }


def _status_codex() -> dict:
    text = ""
    if _CODEX_CONFIG.exists():
        try:
            text = _CODEX_CONFIG.read_text(encoding="utf-8")
        except OSError:
            return {"agent": "codex", "connected": False, "error": "unreadable config.toml"}

    entry = _entry(_read_state()[0], "codex")
    return {
        "agent": "codex",
        "installed": _CODEX_CONFIG.exists(),
        "connected": _CODEX_BEGIN in text,
        "base_url": entry.get("gateway_url"),
        "auth_mode": entry.get("auth_mode"),
        "model": entry.get("model"),
        "connected_at": entry.get("connected_at"),
        "path": str(_CODEX_CONFIG),
    }


# --------------------------------------------------------------------------- #
# Public API
# --------------------------------------------------------------------------- #
def connect_agent(
    agent: str,
    api_url: Optional[str] = None,
    api_key: Optional[str] = None,
    model: Optional[str] = None,
    api_key_env: Optional[str] = None,
    refresh_seconds: Optional[int] = None,
) -> dict:
    """Point ``agent`` at the qBraid AI proxy.

    Args:
        agent: One of :data:`SUPPORTED_AGENTS`.
        api_url: Override the qBraid API base (defaults to the configured one).
        api_key: Claude only. Write this key literally instead of using
            ``apiKeyHelper``. Prefer the default — it keeps the key out of
            settings.json.
        model: Model id to pin. Claude Code needs one the proxy recognises,
            since it matches ids exactly; Codex selects it alongside the
            provider. Defaults to a known-good id for Claude.
        api_key_env: Codex only. Use ``env_key`` pointing at this environment
            variable instead of the ``auth`` command.
        refresh_seconds: How often the agent re-runs the token command.
            Lower it where credentials rotate often (Lab pods); raise it to
            spend fewer subprocesses. Defaults to 300.

    Returns:
        dict: Result with ``agent``, ``status``, ``path`` and ``gateway_url``.

    Raises:
        AiGatewayError: If the agent is unknown or its config can't be updated.
    """
    if agent not in SUPPORTED_AGENTS:
        raise AiGatewayError(
            f"Unknown agent '{agent}'. Expected one of: {', '.join(SUPPORTED_AGENTS)}."
        )

    if refresh_seconds is not None and refresh_seconds <= 0:
        raise AiGatewayError("refresh_seconds must be a positive number of seconds.")

    refresh_ms = _TOKEN_REFRESH_MS if refresh_seconds is None else refresh_seconds * 1000

    gateway_url = resolve_gateway_url(api_url)

    if agent == "claude":
        return _connect_claude(gateway_url, api_key, model, refresh_ms)
    return _connect_codex(gateway_url, model, api_key_env, refresh_ms)


def disconnect_agent(agent: str) -> dict:
    """Restore ``agent``'s configuration to what it was before connecting.

    Args:
        agent: One of :data:`SUPPORTED_AGENTS`.

    Returns:
        dict: Result with ``agent`` and ``status``.

    Raises:
        AiGatewayError: If the agent is unknown or its config can't be updated.
    """
    if agent not in SUPPORTED_AGENTS:
        raise AiGatewayError(
            f"Unknown agent '{agent}'. Expected one of: {', '.join(SUPPORTED_AGENTS)}."
        )

    if agent == "claude":
        return _disconnect_claude()
    return _disconnect_codex()


def gateway_status() -> dict:
    """Report which agents are currently routed through the proxy.

    Returns:
        dict: Mapping of agent name to its status dict.
    """
    return {"claude": _status_claude(), "codex": _status_codex()}
